const input = $input.first().json;
const event = input.event || input;
const context = input.context || {};
const product = context.product || {};
const inv = context.inventory || {};
const qty = inv.quantity !== undefined ? inv.quantity : (context.rawPayload?.inventory ?? product.inventory ?? null);
const sales24h = inv.salesLast24h || context.salesVelocity || context.rawPayload?.salesLast24h || 0;

if (qty === null || qty === undefined) {
  return [{
    json: {
      agent: 'inventory_rescue',
      decision: 'HUMAN_REVIEW',
      reason: 'Missing inventory quantity',
      confidence: 0,
      action: 'CREATE_TASK',
      channel: 'slack',
      message: '',
      escalate: true,
      priority: 'high',
      customerId: '',
      orderId: '',
      status: 'error_missing_data',
      risk: 'UNKNOWN'
    }
  }];
}

const daysOfStock = sales24h > 0 ? (qty / sales24h) : (qty > 0 ? 999 : 0);

return [{
  json: {
    event,
    context,
    product,
    quantity: qty,
    salesLast24h: sales24h,
    daysOfStock: Math.round(daysOfStock * 10) / 10,
    productId: event.productId || product.id || '',
    productName: product.name || context.rawPayload?.name || 'Product'
  }
}];

const item = $input.first().json;
let text = item.text || item.output || JSON.stringify(item);
text = String(text).replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    risk: 'HIGH_RISK',
    decision: 'SLACK_ALERT',
    reason: 'AI parse failed — default to alert',
    confidence: 0.1,
    action: 'SLACK_ALERT',
    channel: 'slack',
    message: '',
    escalate: true,
    priority: 'high'
  };
}

const upstream = $('Calculate Stock Metrics').first().json;
const allowed = ['NO_ACTION','REORDER_ALERT','SLACK_ALERT','CREATE_TASK','PROMOTION_REVIEW','SUBSTITUTE_PRODUCT_RECOMMENDATION'];
if (!allowed.includes(parsed.decision)) {
  parsed.decision = 'SLACK_ALERT';
}

return [{
  json: {
    agent: 'inventory_rescue',
    decision: parsed.decision,
    reason: parsed.reason || '',
    confidence: Number(parsed.confidence) || 0,
    action: parsed.action || parsed.decision,
    channel: 'slack',
    message: parsed.message || '',
    escalate: !!parsed.escalate || ['HIGH_RISK','CRITICAL'].includes(parsed.risk),
    priority: parsed.priority || 'medium',
    risk: parsed.risk || 'WATCH',
    customerId: '',
    orderId: '',
    productId: upstream.productId,
    status: 'decided',
    quantity: upstream.quantity,
    daysOfStock: upstream.daysOfStock
  }
}];

const d = $input.first().json;
return [{
  json: {
    ...d,
    status: d.escalate ? 'escalated' : 'alerted'
  }
}];
